SELECT COUNT(*) AS total_entries
FROM core c
WHERE EXISTS (
    SELECT 1 FROM show_rollups sr WHERE sr.srkeys = c.content_key
) AND EXISTS (
    SELECT 1 FROM rollups r, show_rollups sr2 
    WHERE r.tierkey = sr2.srlinks AND sr2.srkeys = c.content_key AND r.tierkey = 1
);

SELECT COUNT(DISTINCT c.content_title) AS total_entries
FROM core c
INNER JOIN show_rollups sr ON c.content_key = sr.srkeys;

